sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float redMix;
uniform float greenMix;
uniform float blueMix;
uniform float cross;

half4 main(float2 coord){half4 c=image.eval(coord);half3 s=c.rgb/max(c.a,0.0001);half r=s.r*redMix+s.g*cross;half g=s.g*greenMix+s.b*cross;half b=s.b*blueMix+s.r*cross;return half4(clamp(half3(r,g,b),half3(0),half3(1))*c.a,c.a);}
